pub fn parse_http_input(text: &str) -> Result<HttpInput, Error> { read_http_input(Raw::parse_exact(text)?) }
pub fn encode_http_input(value: &HttpInput) -> Result<String, Error> { let mut output = String::new(); write_http_input(value, &mut output)?; Ok(output) }
pub fn encode_message(value: &ClientMessage) -> Result<String, Error> {
let mut output = String::new();
match value { ClientMessage::SessionStart(value) => write_session_start(value, &mut output)?,
ClientMessage::TextChunk(value) => write_text_chunk(value, &mut output)?,
ClientMessage::TextDone(value) => write_text_done(value, &mut output)?, }
Ok(output)
}
pub fn decode_message(value: Message) -> Result<ServerMessage, Error> {
let text = match value { Message::Binary(value) => return Ok(ServerMessage::AudioChunk(value)), Message::Text(text) => text };
let value = Raw::parse_exact(&text)?;
if let Ok(value) = read_session_ready(value) { return Ok(ServerMessage::SessionReady(value)); }
if let Ok(value) = read_segment_start(value) { return Ok(ServerMessage::SegmentStart(value)); }
if let Ok(value) = read_segment_done(value) { return Ok(ServerMessage::SegmentDone(value)); }
if let Ok(value) = read_segment_skipped(value) { return Ok(ServerMessage::SegmentSkipped(value)); }
if let Ok(value) = read_session_done(value) { return Ok(ServerMessage::SessionDone(value)); }
if let Ok(value) = read_session_error(value) { return Ok(ServerMessage::SessionError(value)); }
Err(Error)
}
pub async fn stream_speech(value: &HttpInput, api_key: &str, base_url: &str, transport: &dyn HttpTransport) -> Result<HttpResponse, TransportError> {
let body = encode_http_input(value)?;
let url = endpoint::append(base_url, "/tts-stream").ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidInput, "Invalid CAMB HTTP endpoint URL"))?;
transport.send(HttpRequest { method: "POST".into(), url,
headers: vec![("x-api-key".into(), api_key.into()), ("content-type".into(), "application/json".into())], body: body.into_bytes() }).await
}
